private double calcCoilConstant(FlowUnit flowUnit, double maxUnitLength) {
        double unitBaseLength = flowUnit.getBaselineLength();
        double relativeUnitLength = unitBaseLength / maxUnitLength;
        double coilSpringConstant = (-model.getMinUnitLengthSpringConstant()
                + model.getMaxUnitLengthSpringConstant()) * relativeUnitLength
                + model.getMinUnitLengthSpringConstant();
        return coilSpringConstant;
    }

private Force calcCounterTorsionForce(Flow bezierStream) {
        Point midPt = bezierStream.getBaseLineMidPoint();
        double deltaX = midPt.x - bezierStream.cPtX();
        double deltaY = midPt.y - bezierStream.cPtY();
        double len = Math.sqrt(deltaX * deltaX + deltaY * deltaY);
        double angAlpha = FastMath.atan2(deltaY, deltaX);
        double baseLineAngle = bezierStream.getBaselineOrientation();
        double diffToBaseNorm = Math.PI / 2 - baseLineAngle + angAlpha;
        double torsionForce = FastMath.sin(diffToBaseNorm) * len;
        double counterTorsionWeight = model.getAntiTorsionWeight();
        double torsionForceX = FastMath.cos(baseLineAngle) * torsionForce * counterTorsionWeight;
        double torsionForceY = FastMath.sin(baseLineAngle) * torsionForce * counterTorsionWeight;
        return new Force(torsionForceX, torsionForceY);
    }

private double angularThrust(double gapAngle) {
