public double crossingMetric(Stream stream, List<Barrier> barriers,
            int minBarrierDistPx, double arrowTipWeight) {
        double totalCrossings = 0;
        for (Barrier barrier : barriers) {
            if (stream.isOverlappingBarrier(barrier, model, minBarrierDistPx)) {
                if (barrier.isArrowBarrier()) {
                    totalCrossings += arrowTipWeight;
                } else {
                    ++totalCrossings;
                }
            }
        }
        return totalCrossings;
    }

