private boolean locateControlSpotWithoutOverlapsInsideSpanCubeWithFlexibleMinGap(Flow stream, List<Obstacle> barriers) {
        // 
        int minBarrierGapPx = model.getMinBarrierGapPx();
        while (true) {
            boolean foundSpot = locateControlSpotWithoutOverlapsInsideSpanCube(
                    stream, barriers, minBarrierGapPx);
            if (foundSpot) {
                return true;
            }
            if (minBarrierGapPx == 0) {
                return false;
            }
            // half minimum distance between stream and barriers
            minBarrierGapPx /= 2;
        }
    }

public void symmetrizeStreams() {
        // nodes and arrowheads are obstacles
        List<Obstacle> barrierList = getObstaclesFromCachedCurves(dataModel);

        RangeboxEnforcer rangeboxController = new RangeboxEnforcer(dataModel);
        Iterator<Flow> streamIterator = dataModel.streamIterator();
        while (streamIterator.hasNext()) {
            Flow stream = streamIterator.next();
            if (stream.isLocked()) {
                continue;
            }
            symmetrizeStream(stream, barrierList, rangeboxController);
        }
    }

