public static void transfer(File fileData, OutputStream targetStream) throws IOException {
    byte[] dataBuffer = new byte[4096];
    FileInputStream sourceStream = new FileInputStream(fileData);
    try {
      int bytesRead;
      while ((bytesRead = sourceStream.read(dataBuffer)) >= 0) targetStream.write(dataBuffer, 0, bytesRead);
    } finally {
      sourceStream.close();
    }
  }

