@NonNull
        static WindowInsets relayToUiElementIfNeeded(@NonNull View uiElement, @NonNull WindowInsets windowInsetsData) {
            // If the app set an on apply window listener, it will be called after this
            // and will decide whether to call the view's onApplyWindowInsets.
            if (uiElement.getTag(R.id.tag_on_apply_window_listener) != null) {
                return windowInsetsData;
            }
            return uiElement.onApplyWindowInsets(windowInsetsData);
        }

