public String dispatchAsyncCommand( Channel commChannel, final String cmdText )
    {
        /*
         * Send synchronously to get the Task-UUID to return, the results of the actual 
         * job request will be returned by the server as an async event.
         */
        EslMessage replyEvent = sendSyncSingleLineCommand( commChannel, cmdText );
        if ( replyEvent.hasHeader( Name.TASK_UUID ) )
        {
            return replyEvent.getHeaderValue( Name.TASK_UUID );
        }
        else
        {
            throw new IllegalStateException( "Missing Task-UUID header in bgapi response" );
        }
    }

